head.script:
scwin.onpageload = function() {
    requires("uiplugin.popup"); //팝업을 사용하기 위해 반드시 포함되어야 한다.
    console.log("openPopup_wframe.xml");
    debugger;
};
scwin.onpageunload = function() {};
scwin.popup_callbackFn = function(e) {
    console.log("callback Function");
    alert("콜백함수");
}
scwin.trigger1_onclick = function(e) {
    //var url="./selectbox_wframe_tooltip.xml";
    var url = "selectbox_tooltipFormatter_WEFF-633_(WSQ-3978)_sub.xml";
    //var url="./selectbox_tooltip.xml";
    //var url="./input_maxByteLength.xml";
    var jsonObj = dataList1.getAllJSON();
    var dataObj = {
        type: "json",
        data: {
            fileName: "file.mrd",
            parent_dataList: jsonObj,
            callbackFn: "scwin.popup_callbackFn"
        },
        name: "paramObj"
    };
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "440px",
        height: "300px"
        //, useIframe: false
        //, dataObject: dataObj
    };
    //debugger;
    $p.openPopup(url, options);
};
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).innerText == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('popup1_wframe_selectbox1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_2_balloonTip').style.zIndex != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
